  "sectors.eyebrow": { en: "§ Sectors", fr: "§ Secteurs", de: "§ Bereiche", zh: "§ 业务领域", es: "§ Sectores", ar: "§ القطاعات" },
  "sectors.title.a": { en: "Beyond the crop.", fr: "Au-delà de la culture.", de: "Jenseits der Ernte.", zh: "不止于作物。", es: "Más allá del cultivo.", ar: "أبعد من المحصول." },
  "sectors.title.b": { en: "One integrated operation.", fr: "Une opération intégrée.", de: "Ein integrierter Betrieb.", zh: "一体化运营。", es: "Una operación integrada.", ar: "عملية متكاملة واحدة." },
  "sectors.lede": {
    en: "Cultivation is one part of the work. Around it sit the operations that make export-grade delivery possible — herds on pasture, ponds in the basin, and the handling infrastructure between farm and container.",
    fr: "La culture n'est qu'une partie du travail. Autour s'organisent les opérations qui rendent possible une livraison de qualité export — troupeaux au pâturage, étangs dans le bassin, et toute l'infrastructure de manutention entre la ferme et le conteneur.",
    de: "Anbau ist nur ein Teil der Arbeit. Drumherum stehen die Abläufe, die exportreife Lieferungen erst möglich machen — Herden auf Weiden, Teiche im Becken und die Handhabungsinfrastruktur zwischen Hof und Container.",
    zh: "种植只是工作的一部分。围绕它的是让出口级交付成为可能的各项运营——牧场上的牲畜、流域里的鱼塘,以及农场到集装箱之间的全部处理设施。",
    es: "El cultivo es una parte del trabajo. A su alrededor se ordenan las operaciones que hacen posible la entrega de grado exportación — rebaños en pastura, estanques en la cuenca, y la infraestructura de manejo entre la finca y el contenedor.",
    ar: "الزراعة جزء من العمل. وحولها تتموضع العمليات التي تجعل التسليم بدرجة التصدير ممكنًا — قطعان في المراعي، وأحواض في الحوض، والبنية التحتية للمناولة بين المزرعة والحاوية.",
  },
  "sectors.cta.visit": { en: "Arrange a site visit", fr: "Organiser une visite", de: "Besichtigung vereinbaren", zh: "安排实地参观", es: "Organizar una visita", ar: "رتّب زيارة ميدانية" },
  "sectors.cta.catalogue": { en: "See the catalogue", fr: "Voir le catalogue", de: "Katalog ansehen", zh: "查看目录", es: "Ver el catálogo", ar: "اطّلع على الكتالوج" },
