  "sector.livestock.name": { en: "Livestock", fr: "Élevage", de: "Viehzucht", zh: "畜牧", es: "Ganadería", ar: "الثروة الحيوانية" },
  "sector.livestock.summary": {
    en: "Cattle, goats and poultry raised on rotational pasture along the Sanaga floodplain.",
    fr: "Bovins, caprins et volaille élevés en pâturage tournant le long de la plaine alluviale de la Sanaga.",
    de: "Rinder, Ziegen und Geflügel auf Rotationsweiden entlang der Sanaga-Aue.",
    zh: "在萨纳加河漫滩沿岸采用轮牧方式饲养的牛、羊与家禽。",
    es: "Bovinos, caprinos y aves criados en pastoreo rotacional a lo largo de la llanura del Sanaga.",
    ar: "أبقار وماعز ودواجن تُربى بالرعي الدوري على سهل نهر الساناغا.",
  },
  "sector.livestock.body": {
    en: "Free-range herds and pens managed under veterinary protocol. Feed sourced from our own cereal harvest where possible, animals tracked from birth, and slaughter coordinated through partner abattoirs to retail and HORECA channels.",
    fr: "Troupeaux en plein air et enclos gérés sous protocole vétérinaire. Alimentation issue, autant que possible, de nos propres récoltes céréalières ; animaux suivis depuis la naissance ; abattage coordonné via des abattoirs partenaires pour les circuits retail et HORECA.",
    de: "Freilaufherden und Pferche unter tierärztlichem Protokoll. Futter, wo möglich, aus eigener Getreideernte; Tiere von Geburt an erfasst; Schlachtung über Partnerschlachthöfe in Richtung Einzelhandel und HORECA.",
    zh: "自由放养的畜群与圈舍按兽医规程管理。饲料尽可能取自我们自有的谷物收成,动物从出生即可追溯,屠宰通过合作屠宰厂协调,供应零售及 HORECA 渠道。",
    es: "Rebaños en pastoreo libre y corrales gestionados bajo protocolo veterinario. Alimento procedente, cuando es posible, de nuestra propia cosecha cerealera; animales rastreados desde el nacimiento; sacrificio coordinado en mataderos asociados para canales retail y HORECA.",
    ar: "قطعان حرة وحظائر تُدار وفق بروتوكول بيطري. العلف يُستمد قدر الإمكان من محاصيلنا من الحبوب، والحيوانات تُتابَع منذ الولادة، ويُنسَّق الذبح عبر مسالخ شريكة لقنوات التجزئة وقطاع الفنادق والمطاعم.",
  },
