  "sector.fish.name": { en: "Fish farming", fr: "Pisciculture", de: "Fischzucht", zh: "水产养殖", es: "Piscicultura", ar: "الاستزراع السمكي" },
  "sector.fish.summary": {
    en: "Freshwater aquaculture ponds along the Edéa basin — tilapia and African catfish.",
    fr: "Étangs d'aquaculture en eau douce dans le bassin d'Édéa — tilapia et silure africain.",
    de: "Süßwasser-Aquakulturteiche im Edéa-Becken — Tilapia und afrikanischer Wels.",
    zh: "埃代阿流域的淡水养殖塘——罗非鱼与非洲鲇鱼。",
    es: "Estanques de acuicultura de agua dulce en la cuenca de Edéa — tilapia y bagre africano.",
    ar: "أحواض استزراع للمياه العذبة في حوض إيديا — البلطي والقرموط الإفريقي.",
  },
  "sector.fish.body": {
    en: "Earthen and lined ponds operated under continuous water-quality monitoring. Fingerlings sourced from accredited hatcheries, feed protocols documented per pond, and harvest scheduled to match wholesale demand cycles in Douala and Yaoundé.",
    fr: "Étangs en terre et bâchés exploités sous suivi continu de la qualité de l'eau. Alevins issus d'écloseries accréditées, protocoles d'alimentation documentés par étang, et récolte planifiée selon les cycles de demande de gros à Douala et Yaoundé.",
    de: "Erd- und Folienteiche unter kontinuierlicher Wasserqualitätskontrolle. Setzlinge aus zertifizierten Brütereien, Fütterungsprotokolle pro Teich dokumentiert; Ernte abgestimmt auf die Großhandelszyklen in Douala und Yaoundé.",
    zh: "土塘与衬塘均处于持续水质监测之下。鱼苗源自认证孵化场,饲喂规程按塘记录,捕捞排期匹配杜阿拉与雅温得的批发需求周期。",
    es: "Estanques de tierra y revestidos operados con monitoreo continuo de calidad del agua. Alevines de criaderos acreditados, protocolos de alimentación documentados por estanque, y cosecha programada según los ciclos mayoristas de Douala y Yaundé.",
    ar: "أحواض ترابية ومُبطّنة تُدار بمراقبة مستمرة لجودة المياه. الزريعة من مفقسات معتمدة، وبروتوكولات التغذية موثّقة لكل حوض، ويُجدوَل الحصاد ليتوافق مع دورات الطلب بالجملة في دوالا وياوندي.",
  },
  "sector.fish.f1.k": { en: "Species", fr: "Espèces", de: "Arten", zh: "品种", es: "Especies", ar: "الأنواع" },
