  "sector.cold-house.name": { en: "Cold house", fr: "Chambre froide", de: "Kühlhaus", zh: "冷藏库", es: "Cámara frigorífica", ar: "غرفة التبريد" },
  "sector.cold-house.summary": {
    en: "Temperature-controlled storage between Douala and Edéa, sized for export pre-staging.",
    fr: "Stockage à température contrôlée entre Douala et Édéa, dimensionné pour le pré-acheminement à l'export.",
    de: "Temperaturkontrollierte Lagerung zwischen Douala und Edéa, dimensioniert für die Export-Vorstufung.",
    zh: "位于杜阿拉与埃代阿之间的温控仓储,按出口前置规模设计。",
    es: "Almacenamiento con temperatura controlada entre Douala y Edéa, dimensionado para la preparación previa a la exportación.",
    ar: "تخزين بدرجة حرارة مضبوطة بين دوالا وإيديا، بحجم يلائم التحضير المسبق للتصدير.",
  },
  "sector.cold-house.body": {
    en: "Multi-zone cold rooms holding produce at the temperature each crop demands — pineapple at one set point, leafy garden produce at another, animal protein at a third. Power is grid-with-backup, and every pallet carries a temperature log from intake to dispatch.",
    fr: "Chambres froides multi-zones tenant chaque produit à sa température — l'ananas à un point de consigne, les légumes-feuilles à un autre, les protéines animales à un troisième. Alimentation réseau avec secours, et chaque palette porte un relevé de température de l'entrée à la sortie.",
    de: "Mehrzonen-Kühlräume halten jedes Produkt auf seiner Temperatur — Ananas bei einem Sollwert, Blattgemüse bei einem anderen, tierisches Eiweiß bei einem dritten. Stromversorgung mit Backup, und jede Palette führt ein Temperaturprotokoll von Annahme bis Versand.",
    zh: "多温区冷库,按各品类所需温度存放——菠萝、叶菜、动物蛋白各设温度。电力为电网加备用电源,每板均带从入库到出库的温度记录。",
    es: "Cámaras multi-zona que mantienen cada producto a su temperatura — piña a un set point, hortalizas de hoja a otro, proteína animal a un tercero. Energía red con respaldo y cada pallet con bitácora de temperatura desde recepción hasta despacho.",
    ar: "غرف تبريد متعددة المناطق تحفظ كل منتج عند درجة حرارته — الأناناس عند نقطة، والخضروات الورقية عند أخرى، والبروتين الحيواني عند ثالثة. التغذية من الشبكة مع احتياطي، وكل بليت يحمل سجل حرارة من الاستلام حتى الإرسال.",
  },
  "sector.cold-house.f1.k": { en: "Zones", fr: "Zones", de: "Zonen", zh: "温区", es: "Zonas", ar: "المناطق" },
  "sector.cold-house.f1.v": { en: "Multi-temperature", fr: "Multi-températures", de: "Mehrtemperatur", zh: "多温", es: "Multi-temperatura", ar: "متعددة الحرارة" },
  "sector.cold-house.f2.k": { en: "Backup", fr: "Secours", de: "Backup", zh: "备用", es: "Respaldo", ar: "الاحتياط" },
