  "sector.cold-house.f3.v": { en: "Per-pallet record", fr: "Relevé par palette", de: "Pro-Paletten-Protokoll", zh: "按板记录", es: "Registro por pallet", ar: "سجل لكل بليت" },

  "sector.package-house.name": { en: "Package house", fr: "Conditionnement", de: "Verpackungshaus", zh: "包装中心", es: "Casa de empaque", ar: "بيت التعبئة" },
  "sector.package-house.summary": {
    en: "Sorting, calibration and packing facility, sized for container-grade export lots.",
    fr: "Atelier de tri, calibrage et conditionnement, dimensionné pour des lots export au format conteneur.",
    de: "Sortier-, Kalibrier- und Verpackungsanlage, dimensioniert für containerfähige Exportchargen.",
    zh: "分级、校准与包装设施,规模匹配集装箱级出口批次。",
    es: "Instalación de selección, calibración y empaque dimensionada para lotes de exportación a escala contenedor.",
    ar: "منشأة فرز ومعايرة وتعبئة بحجم يناسب دفعات التصدير على مستوى الحاوية.",
  },
  "sector.package-house.body": {
    en: "Hand-sorting tables, weight calibration, moisture checks and ISPM-15 pallet preparation under one roof. Crops are graded against the buyer's specification, packed in jute, carton or vacuum as required, and labelled in French and English before container loading.",
    fr: "Tables de tri manuel, calibrage pondéral, contrôle d'humidité et préparation de palettes ISPM-15 sous un même toit. Les produits sont gradés selon le cahier des charges de l'acheteur, conditionnés en jute, carton ou sous vide, et étiquetés en français et anglais avant chargement.",
    de: "Handsortiertische, Gewichtskalibrierung, Feuchteprüfung und ISPM-15-Palettenvorbereitung unter einem Dach. Erzeugnisse werden nach Käuferspezifikation klassiert, in Jute, Karton oder Vakuum verpackt und vor dem Verladen zweisprachig (FR/EN) etikettiert.",
    zh: "在同一屋檐下进行人工分级、称重校准、含水率检测与 ISPM-15 木托板处理。按买家规范分级,按需以麻袋、纸箱或真空包装,装柜前以法英双语贴标。",
    es: "Mesas de selección manual, calibración por peso, controles de humedad y preparación de pallets ISPM-15 bajo un mismo techo. Los productos se clasifican según la especificación del comprador, se empacan en yute, cartón o vacío y se etiquetan en francés e inglés antes del cargue.",
    ar: "طاولات فرز يدوي، ومعايرة الوزن، وفحوصات الرطوبة، وتجهيز بليتات ISPM-15 تحت سقفٍ واحد. تُدرَّج المحاصيل وفق مواصفات المشتري، وتُعبَّأ في الخيش أو الكرتون أو التفريغ حسب الحاجة، وتُلصق ببطاقات بالفرنسية والإنجليزية قبل التحميل.",
  },
  "sector.package-house.f1.k": { en: "Operations", fr: "Opérations", de: "Operationen", zh: "工序", es: "Operaciones", ar: "العمليات" },
  "sector.package-house.f1.v": { en: "Sort · Calibrate · Pack", fr: "Trier · Calibrer · Conditionner", de: "Sortieren · Kalibrieren · Verpacken", zh: "分级 · 校准 · 包装", es: "Clasificar · Calibrar · Empacar", ar: "فرز · معايرة · تعبئة" },
