  // ───── About ─────
  "about.eyebrow": { en: "About — The House", fr: "À propos — La Maison", de: "Über uns — Das Haus", zh: "关于我们 — 公司", es: "Nosotros — La Casa", ar: "من نحن — الدار" },
  "about.title.a": { en: "Land first.", fr: "La terre d'abord.", de: "Boden zuerst.", zh: "土地为先。", es: "La tierra primero.", ar: "الأرض أولًا." },
  "about.title.b": { en: "Ledger second.", fr: "Le registre ensuite.", de: "Bücher danach.", zh: "账册其次。", es: "El libro después.", ar: "الدفتر ثانيًا." },
  "about.intro1": {
    en: "Green Gold Agro Farm was founded on a simple commercial premise: Cameroon grows extraordinary produce, and the world's serious buyers will pay accordingly when the produce arrives sorted, sealed, and documented.",
    fr: "Green Gold Agro Farm est née d'un postulat commercial simple : le Cameroun produit des denrées extraordinaires, et les acheteurs sérieux du monde paieront en conséquence lorsque ces denrées arrivent triées, scellées et documentées.",
    de: "Green Gold Agro Farm wurde auf einer einfachen kommerziellen Prämisse gegründet: Kamerun bringt außergewöhnliche Erzeugnisse hervor, und die seriösen Käufer der Welt zahlen entsprechend, wenn die Ware sortiert, versiegelt und dokumentiert ankommt.",
    zh: "Green Gold Agro Farm 创立于一个朴素的商业前提:喀麦隆出产卓越的农产品,而当其分级、封装、文件齐备地抵达时,全球的严肃买家会给出相称的价格。",
    es: "Green Gold Agro Farm nació de una premisa comercial simple: Camerún cultiva productos extraordinarios y los compradores serios del mundo pagarán acorde cuando lleguen clasificados, sellados y documentados.",
    ar: "تأسست Green Gold Agro Farm على فرضية تجارية بسيطة: الكاميرون تنتج محاصيل استثنائية، وسيدفع المشترون الجادّون في العالم بما يليق حين تصل مفروزةً ومختومةً وموثّقة.",
  },
  "about.intro2": {
    en: "We work across the Centre, South, West and North-West regions, partnering with cooperatives whose practices we audit and improve season by season.",
    fr: "Nous opérons dans les régions du Centre, du Sud, de l'Ouest et du Nord-Ouest, en partenariat avec des coopératives dont nous auditons et améliorons les pratiques saison après saison.",
    de: "Wir arbeiten in den Regionen Zentrum, Süden, Westen und Nordwesten und partnern mit Kooperativen, deren Praktiken wir Saison für Saison prüfen und verbessern.",
    zh: "我们的业务覆盖中部、南部、西部及西北部各区,与合作社结成伙伴关系,逐季审核并改进其作业方式。",
    es: "Trabajamos en las regiones Centro, Sur, Oeste y Noroeste, asociándonos con cooperativas cuyas prácticas auditamos y mejoramos temporada a temporada.",
    ar: "نعمل في مناطق الوسط والجنوب والغرب والشمال الغربي، بالشراكة مع تعاونيات نراجع ممارساتها ونطوّرها موسمًا تلو الآخر.",
  },
  "about.posture.eyebrow": { en: "Posture", fr: "Posture", de: "Haltung", zh: "立场", es: "Postura", ar: "الموقف" },
  "about.posture.title.a": { en: "Sustainable, but never", fr: "Durable, mais jamais", de: "Nachhaltig, aber niemals", zh: "可持续,但绝不", es: "Sostenible, pero nunca", ar: "مستدام، ولكن أبدًا ليس" },
  "about.posture.title.soft": { en: "soft", fr: "complaisant", de: "weich", zh: "软弱", es: "blando", ar: "ليّنًا" },
  "about.posture.p1": {
    en: "Our sustainability is operational, not decorative. Soil rotation, agroforestry corridors, water-line discipline and a refusal to over-extract any one parcel are not ESG language — they are the conditions under which next year's harvest exists.",
    fr: "Notre durabilité est opérationnelle, pas décorative. Rotation des sols, corridors agroforestiers, discipline hydrique et refus de surexploiter la moindre parcelle ne sont pas un vocabulaire ESG — ce sont les conditions d'existence de la récolte de l'année suivante.",
    de: "Unsere Nachhaltigkeit ist operativ, nicht dekorativ. Bodenrotation, Agroforst-Korridore, Wasserdisziplin und der Verzicht auf Überausbeutung sind keine ESG-Floskeln — sie sind die Bedingungen, unter denen die nächste Ernte überhaupt entsteht.",
    zh: "我们的可持续性是运营层面的,不是装饰。土壤轮作、农林复合走廊、水线纪律,以及拒绝对任一地块过度索取——这些不是 ESG 词藻,而是来年收成得以存在的前提。",
    es: "Nuestra sostenibilidad es operativa, no decorativa. Rotación de suelos, corredores agroforestales, disciplina hídrica y la negativa a sobreexplotar cualquier parcela no son lenguaje ESG — son las condiciones bajo las que existe la próxima cosecha.",
    ar: "استدامتنا تشغيلية لا تزيينية. تناوب التربة، وممرات الزراعة الحرجية، وانضباط المياه، ورفض الاستنزاف المفرط لأي قطعة — ليست لغة ESG، بل شروط وجود حصاد العام القادم.",
  },
  "about.posture.p2": {
    en: "Commercial seriousness sits on top of that: bilingual contracts, traceable lots, ISPM-15 compliant pallets, and a documentation culture our buyers can hand to their own customs broker without revision.",
    fr: "Sur cette base s'ajoute la rigueur commerciale : contrats bilingues, lots traçables, palettes conformes ISPM-15, et une culture documentaire que nos acheteurs peuvent transmettre telle quelle à leur propre courtier en douane.",
    de: "Darauf baut die kommerzielle Disziplin: zweisprachige Verträge, rückverfolgbare Chargen, ISPM-15-konforme Paletten und eine Dokumentationskultur, die unsere Käufer ohne Korrektur an ihren Zollagenten weitergeben können.",
    zh: "在此之上是商务上的严谨:双语合同、可追溯批次、ISPM-15 合规木托盘,以及让买家可不加修改即转交其报关行的文档文化。",
    es: "Sobre eso descansa la seriedad comercial: contratos bilingües, lotes trazables, pallets conformes ISPM-15 y una cultura de documentación que nuestros compradores pueden entregar a su agente aduanal sin revisión.",
    ar: "وفوق ذلك تأتي الجدية التجارية: عقود ثنائية اللغة، ودفعات قابلة للتتبع، وبليتات مطابقة لـ ISPM-15، وثقافة توثيق يمكن لمشترينا تسليمها إلى مخلّص جماركهم دون تعديل.",
  },
